,0.009611417073756456,0.00017341971397399902,0.00015836145030334592},pedal=0.9800000190734863},[2232]={orig={1.9837945699691772,-0.025596361607313156,0.008344481699168682,0.004177263006567955,0.4175410866737366,-0.0003909652878064662},spread={0.0016340017318725586,0.000466005876660347,0.0026854942552745342,0.009133703075349331,0.00013622641563415527,0.0001298858260270208},pedal=0.9800000190734863},[2268]={orig={1.9838266372680664,-0.026102039963006973,0.008397718891501427,0.003703392343595624,0.4175195097923279,-0.0003138660977128893},spread={0.0016340017318725586,0.0005472376942634583,0.0027976403944194317,0.008660207502543926,0.00010454654693603516,7.512461161240935e-05},pedal=0.9800000190734863},[2304]={orig={1.9838290214538574,-0.026481304317712784,0.008450339548289776,0.003132586134597659,0.41750019788742065,-0.00028665244462899864},spread={0.0016340017318725586,0.0005472376942634583,0.0027976403944194317,0.008192921755835414,8.296966552734375e-05,7.512461161240935e-05},pedal=0.9800000190734863}}}
